import { expect } from "chai";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";

import { deployOpenVmReceiptVerifier } from "../../scripts/openVm";
import { ethers } from "../fixtures/connection";

// Generated by crates/openvm-prover/tests/checkpoints/run.py; no proving runs in this suite.
const fixture = process.env.OPENVM_CHECKPOINT_FIXTURE;

(fixture ? describe : describe.skip)("OpenVM checkpoint receipt", function () {
  this.timeout(120_000);

  it("accepts the genuine seal and rejects changed proof, journal and identity", async function () {
    expect((await ethers.provider.getNetwork()).chainId).to.equal(31337n);
    const directory = path.resolve(fixture!);
    const config = JSON.parse(
      readFileSync(path.join(directory, "config.json"), "utf8"),
    );
    const seal = readFileSync(path.join(directory, "seal.bin"));
    const journal = readFileSync(path.join(directory, "journal.bin"));
    expect(seal.length).to.equal(1856);
    expect(journal.length).to.equal(288);
    const { receipt, halo2Verifier } = await deployOpenVmReceiptVerifier(
      ethers,
      {
        OPENVM_APP_EXE_COMMIT: config.app_commit.app_exe_commit,
        OPENVM_APP_VM_COMMIT: config.app_commit.app_vm_commit,
        OPENVM_VERIFIER_ARTIFACT: config.verifier_artifact,
        OPENVM_VERIFIER_SHA256: config.verifier_sha256,
      },
    );
    const image = ethers.keccak256(
      ethers.AbiCoder.defaultAbiCoder().encode(
        ["bytes32", "address", "bytes32", "bytes32"],
        [
          ethers.id("INTERFOLD_OPENVM_RECEIPT_V1"),
          halo2Verifier,
          config.app_commit.app_exe_commit,
          config.app_commit.app_vm_commit,
        ],
      ),
    );
    expect(await receipt.imageId()).to.equal(image);
    const digest = (bytes: Uint8Array) =>
      `0x${createHash("sha256").update(bytes).digest("hex")}`;
    const gas = { gasLimit: 16_000_000 };
    await receipt.verify.staticCall(seal, image, digest(journal), gas);

    const changedSeal = Buffer.from(seal);
    changedSeal[100] ^= 1;
    await expect(
      receipt.verify.staticCall(changedSeal, image, digest(journal), gas),
    ).to.revert(ethers);
    const changedJournal = Buffer.from(journal);
    changedJournal[0] ^= 1;
    await expect(
      receipt.verify.staticCall(seal, image, digest(changedJournal), gas),
    ).to.revert(ethers);
    const changedImage = ethers.getBytes(image);
    changedImage[0] ^= 1;
    await expect(
      receipt.verify.staticCall(seal, changedImage, digest(journal), gas),
    ).to.revert(ethers);
    const changedExe = ethers.getBytes(config.app_commit.app_exe_commit);
    changedExe[31] ^= 1;
    const other = await ethers.deployContract("OpenVmReceiptVerifier", [
      halo2Verifier,
      changedExe,
      config.app_commit.app_vm_commit,
    ]);
    await other.waitForDeployment();
    await expect(
      other.verify.staticCall(
        seal,
        await other.imageId(),
        digest(journal),
        gas,
      ),
    ).to.revert(ethers);
  });
});
